// Occupation cascade — the guided Industry (q1) → Role area (q2) → Occupation
// (q3) picker that resolves a specific job title to one of the ~15 engine
// profiles. Auto-generated from the client's "Tips by Occupation" workbook and
// ported verbatim from reference/deploy-2026-07-07/occ-flow.js (window.OCC_FLOW).
// 180 leaves; `engine` is a PROFILES id, `display` is the shared worksheet's
// friendly name. Helpers below derive the dependent dropdowns (calc.js
// renderPicker cascade). Pure data — safe on client and server.

export interface OccFlowLeaf {
  /** Industry (step 1). */
  q1: string;
  /** Role area (step 2). */
  q2: string;
  /** Specific occupation (step 3) — null when the role area resolves directly. */
  q3: string | null;
  /** Friendly name of the shared worksheet this resolves to. */
  display: string;
  /** PROFILES id the worksheet engine loads. */
  engine: string;
}

