const uniq = (xs: string[]): string[] => Array.from(new Set(xs));

/** Distinct industries (step-1 options), in first-seen order. */
export function occIndustries(): string[] {
  return uniq(OCC_FLOW.map((l) => l.q1));
}

/** Distinct role areas (step-2 options) for an industry. */
export function occRoleAreas(q1: string): string[] {
  return uniq(OCC_FLOW.filter((l) => l.q1 === q1).map((l) => l.q2));
}

/** True when this (industry, role area) has named occupations to pick (step 3
 * required); false when the role area resolves to an engine directly. */
export function occQ3Needed(q1: string, q2: string): boolean {
  return OCC_FLOW.some((l) => l.q1 === q1 && l.q2 === q2 && l.q3 !== null);
}

/** Distinct occupations (step-3 options) for an industry + role area. */
export function occOccupations(q1: string, q2: string): string[] {
  return uniq(OCC_FLOW.filter((l) => l.q1 === q1 && l.q2 === q2 && l.q3 !== null).map((l) => l.q3 as string));
}

/** Resolve the selected path to its leaf (engine + display). q3 is ignored for
 * role areas that resolve directly; matched when the role area needs it. */
export function occResolve(q1: string, q2: string, q3?: string | null): OccFlowLeaf | undefined {
  if (occQ3Needed(q1, q2)) {
    if (!q3) return undefined;
    return OCC_FLOW.find((l) => l.q1 === q1 && l.q2 === q2 && l.q3 === q3);
  }
  return OCC_FLOW.find((l) => l.q1 === q1 && l.q2 === q2);
}
